<script setup lang="ts">
import{computed,ref,onMounted,onUnmounted}from'vue';import{useRouter}from'vue-router';import{MapPin,ChevronRight}from'lucide-vue-next';import shapes from'../../assets/map.json';import{summaries,loadSummaries,summaryLoading}from'../../composables/useLocations';import{percent,number}from'../../utils/format';const router=useRouter(),hover=ref<string|null>(null),mode=ref('map');onMounted(loadSummaries);const timer=setInterval(()=>{if(!document.hidden)void loadSummaries()},30000);onUnmounted(()=>clearInterval(timer));const active=computed(()=>summaries.value.find(s=>s.uf===hover.value));const levels=['#e6eff5','#bed3e3','#8cb2cf','#5687af','#285b86'];function color(uf:string){const value=summaries.value.find(s=>s.uf===uf)?.progress;return value==null?'#e1e7ec':levels[Math.min(4,Math.floor(value/20))]}const positions:Record<string,[number,number]>={ac:[58,206],am:[132,135],rr:[189,48],ap:[304,50],pa:[286,137],ro:[148,235],mt:[230,257],to:[334,216],ma:[376,153],pi:[399,194],ce:[453,159],rn:[489,180],pb:[489,201],pe:[474,220],al:[487,238],se:[474,255],ba:[402,275],go:[310,303],df:[337,294],ms:[251,347],mg:[383,340],es:[442,350],rj:[414,382],sp:[331,382],pr:[292,414],sc:[306,442],rs:[273,469]};
</script>
<template><section class="panel map-panel"><div class="panel-heading"><div><h2>Apuração pelo Brasil</h2><p>Selecione um estado para explorar</p></div><div class="segmented"><button :class="{active:mode==='map'}" @click="mode='map'">Mapa</button><button :class="{active:mode==='list'}" @click="mode='list'">Lista</button></div></div><div v-if="mode==='map'" class="map-container"><svg viewBox="0 0 530 510" role="group" aria-label="Mapa interativo dos 27 estados brasileiros"><g v-for="s in shapes" :key="s.uf" :aria-label="`${s.name}, ${percent(summaries.find(x=>x.uf===s.uf)?.progress)} apurado. Ver resultados`" tabindex="0" role="link" @mouseenter="hover=s.uf" @mouseleave="hover=null" @focus="hover=s.uf" @blur="hover=null" @keydown.enter="router.push('/estado/'+s.uf)" @keydown.space.prevent="router.push('/estado/'+s.uf)" @click="router.push('/estado/'+s.uf)"><path :d="s.path" :fill="color(s.uf)" :class="{hovered:hover===s.uf}"/><text :x="positions[s.uf]?.[0]??s.x" :y="positions[s.uf]?.[1]??s.y" :class="{darktext:(summaries.find(x=>x.uf===s.uf)?.progress??0)<60}">{{s.uf.toUpperCase()}}</text><title>{{s.name}}</title></g></svg><div v-if="active" class="map-tooltip"><strong>{{active.name}}</strong><span>Apuração: {{percent(active.progress)}}</span><template v-if="active.leader"><small>Mais votado: {{active.leader.name}}</small><b>{{percent(active.leader.percent)}} <small>· {{number(active.leader.votes)}} votos</small></b></template></div></div><div v-else class="map-state-list"><RouterLink v-for="s in shapes.slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))" :key="s.uf" :to="'/estado/'+s.uf"><span>{{s.name}}</span><strong>{{percent(summaries.find(x=>x.uf===s.uf)?.progress)}}</strong><ChevronRight :size="15"/></RouterLink></div><div class="map-legend"><span>Seções totalizadas</span><div><span v-for="c in levels" :key="c" :style="{background:c}"></span></div><small>0%</small><small>100%</small></div><div class="map-caption"><MapPin :size="14"/>{{summaryLoading?'Atualizando os estados…':'27 unidades da Federação'}}<span>Cores indicam o avanço da apuração</span></div></section></template>
